const item = $input.first();
const input = item.json;
const headers = input.headers ?? {};
const signature = headers["x-relayos-signature"];
const timestamp = headers["x-relayos-timestamp"];
const nonce = headers["x-relayos-nonce"];
const rawBodyData = item.binary?.data?.data;
const secret = $env.RELAYOS_WEBHOOK_SECRET;
if (!signature || !timestamp || !nonce || !/^v1=[0-9a-f]{64}$/.test(signature)) throw new Error("Missing or malformed RelayOS signature headers");
if (!/^\d+$/.test(timestamp)) throw new Error("Invalid RelayOS timestamp");
const requestTime = Number(timestamp);
if (!Number.isSafeInteger(requestTime) || Math.abs(Math.floor(Date.now() / 1000) - requestTime) > 300) throw new Error("RelayOS timestamp is outside the five-minute replay window");
if (typeof rawBodyData !== "string" || !rawBodyData) throw new Error("Webhook Raw Body binary data is missing");
if (!secret) throw new Error("RELAYOS_WEBHOOK_SECRET is missing");
const rawBody = Buffer.from(rawBodyData, "base64").toString("utf8");
const crypto = require("crypto");
const canonical = `${timestamp}.${nonce}.${rawBody}`;
const expected = `v1=${crypto.createHmac("sha256", secret).update(canonical, "utf8").digest("hex")}`;
const actualBuffer = Buffer.from(signature, "utf8");
const expectedBuffer = Buffer.from(expected, "utf8");
if (actualBuffer.length !== expectedBuffer.length || !crypto.timingSafeEqual(actualBuffer, expectedBuffer)) throw new Error("Invalid RelayOS signature");
return [{ json: input.body }];
